/**
 * The art atlas.
 *
 * One self-contained HTML page: every generative style, plotted in every theme,
 * as inline SVG. It is generated by the same `renderArt` the decks use, so what
 * the atlas shows is exactly what a slide gets — no separate drawing code to
 * drift, no screenshots to re-export.
 *
 * `--compact` prints a single-theme, small-card version that stays under ~30 KB
 * and can be deployed anywhere as a static page.
 */
import fs from 'node:fs';
import path from 'node:path';
import { escapeXml, sceneToSvg } from './svg.js';
import { ART_LABELS, ART_NOTES, ART_STYLES, artSignature, framedArt, type ArtStyle } from './generative.js';
import { listThemes, loadTheme, resolvePalette, type Theme } from './themes.js';

export interface AtlasOptions {
  out: string;
  /** Theme ids to include. Defaults to every shipped theme (or the first one when compact). */
  themeIds?: string[];
  compact?: boolean;
  seed?: string;
}

function atlasThemes(options: AtlasOptions): Theme[] {
  const ids = options.themeIds && options.themeIds.length > 0
    ? options.themeIds
    : listThemes().map((theme) => theme.id);
  const wanted = options.compact ? ids.slice(0, 2) : ids;
  return wanted.map((id) => loadTheme(id));
}

export interface AtlasResult {
  ok: boolean;
  out: string;
  styles: number;
  themes: number;
  cards: number;
  bytes: number;
}

function card(theme: Theme, style: ArtStyle, width: number, height: number, seedRoot: string): { svg: string; seed: string } {
  const palette = resolvePalette(theme);
  const seed = `${seedRoot}-${theme.id}-${style}`;
  const nodes = framedArt(palette, {
    zone: { x: 0, y: 0, w: width, h: height },
    style,
    seed,
    density: 0.58,
    opacity: 1,
  });
  const svg = sceneToSvg({ width, height, nodes, background: palette.bg });
  // Inline SVG in HTML needs no XML declaration; drop the fixed size so the card
  // scales with the grid instead of overflowing it.
  return { svg: svg.replace(/ width="\d+" height="\d+"/, ' width="100%"'), seed };
}

export function buildAtlasHtml(options: AtlasOptions): string {
  const themes = atlasThemes(options);
  const compact = options.compact === true;
  const width = compact ? 360 : 520;
  const height = compact ? 220 : 320;
  const seedRoot = options.seed ?? 'omni-atlas';
  const cards: Array<{ theme: Theme; style: ArtStyle; svg: string; seed: string }> = [];
  for (const theme of themes) {
    for (const style of ART_STYLES) {
      const built = card(theme, style, width, height, seedRoot);
      cards.push({ theme, style, svg: built.svg, seed: built.seed });
    }
  }

  const sections = themes
    .map((theme) => {
      const own = cards.filter((c) => c.theme.id === theme.id);
      const swatches = [theme.colors.accent, theme.colors.bg_primary, theme.colors.text_primary]
        .map((color) => `<span class="swatch" style="background:${color}"></span>`)
        .join('');
      return `<section class="theme">
      <header class="theme-head">
        <h2>${escapeXml(theme.name)}</h2>
        <p>${escapeXml(theme.description)}</p>
        <p class="meta">${escapeXml(theme.id)} · ${swatches}</p>
      </header>
      <div class="grid">
        ${own
          .map(
            (c) => `<figure class="art">
          <div class="canvas">${c.svg}</div>
          <figcaption>
            <span class="name">${escapeXml(ART_LABELS[c.style])}</span>
            <span class="seed">seed ${artSignature(c.seed)}</span>
            <span class="note">${escapeXml(ART_NOTES[c.style])}</span>
          </figcaption>
        </figure>`,
          )
          .join('\n        ')}
      </div>
    </section>`;
    })
    .join('\n    ');

  const title = compact ? 'omni-carousel · art atlas' : 'omni-carousel · generative art atlas';
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>${escapeXml(title)}</title>
<meta name="description" content="Eight deterministic generative vector styles from the omni-carousel engine, plotted in every theme." />
<style>
  :root {
    --ink: #f3f1ea; --muted: #8e949d; --line: #242a35; --bg: #07080c; --surface: #0e1117; --pen: #6cffc2;
  }
  * { box-sizing: border-box; }
  body { margin: 0; background: var(--bg); color: var(--ink); font: 16px/1.5 Inter, system-ui, -apple-system, "Segoe UI", sans-serif; }
  .wrap { max-width: 1180px; margin: 0 auto; padding: 56px 24px 96px; }
  h1 { font: 700 clamp(30px, 5vw, 54px)/1.05 "Space Grotesk", Inter, sans-serif; letter-spacing: -0.02em; margin: 0 0 12px; }
  .lede { color: var(--muted); max-width: 62ch; margin: 0 0 10px; }
  .stats { display: flex; flex-wrap: wrap; gap: 10px; margin: 26px 0 12px; padding: 0; list-style: none; }
  .stats li { border: 1px solid var(--line); border-radius: 999px; padding: 6px 14px; font: 500 13px/1 "JetBrains Mono", ui-monospace, monospace; color: var(--muted); }
  .stats strong { color: var(--pen); font-weight: 600; }
  section.theme { margin-top: 56px; border-top: 1px solid var(--line); padding-top: 28px; }
  .theme-head h2 { font: 600 22px/1.2 "Space Grotesk", Inter, sans-serif; margin: 0 0 6px; }
  .theme-head p { margin: 0; color: var(--muted); max-width: 70ch; font-size: 14px; }
  .theme-head .meta { margin-top: 10px; font: 500 12px/1 "JetBrains Mono", ui-monospace, monospace; letter-spacing: .08em; text-transform: uppercase; display: flex; align-items: center; gap: 8px; }
  .swatch { width: 14px; height: 14px; border-radius: 3px; border: 1px solid var(--line); display: inline-block; }
  .grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 18px; margin-top: 20px; }
  figure.art { margin: 0; border: 1px solid var(--line); border-radius: 8px; overflow: hidden; background: var(--surface); }
  .canvas { display: block; line-height: 0; }
  .canvas svg { display: block; width: 100%; height: auto; }
  figcaption { padding: 12px 14px 14px; display: grid; gap: 2px; border-top: 1px solid var(--line); }
  .name { font-weight: 600; font-size: 14px; }
  .seed { font: 500 11px/1.4 "JetBrains Mono", ui-monospace, monospace; color: var(--pen); letter-spacing: .08em; }
  .note { color: var(--muted); font-size: 13px; }
  footer { margin-top: 64px; border-top: 1px solid var(--line); padding-top: 20px; color: var(--muted); font-size: 13px; }
  code { font-family: "JetBrains Mono", ui-monospace, monospace; color: var(--ink); }
</style>
</head>
<body>
  <div class="wrap">
    <h1>Eight plots, drawn from a seed</h1>
    <p class="lede">Every composition below is vector geometry generated by <code>core-engine/src/generative.ts</code> from the theme palette and a seed string. No images, no gradients from a library, no network calls. Same seed in, same drawing out — which is what makes a deck reproducible.</p>
    <ul class="stats">
      <li><strong>${ART_STYLES.length}</strong> styles</li>
      <li><strong>${themes.length}</strong> themes</li>
      <li><strong>${cards.length}</strong> plots</li>
      <li><strong>0</strong> network requests</li>
    </ul>
    ${sections}
    <footer>
      Generated by <code>omni-carousel canvas</code> — the same renderer that draws slides.
      ${compact ? '' : 'Full atlas: every style in every theme.'}
    </footer>
  </div>
</body>
</html>
`;
}

export function writeAtlas(options: AtlasOptions): AtlasResult {
  const html = buildAtlasHtml(options);
  fs.mkdirSync(path.dirname(path.resolve(options.out)), { recursive: true });
  fs.writeFileSync(options.out, html, 'utf8');
  const themes = atlasThemes(options);
  return {
    ok: true,
    out: path.resolve(options.out),
    styles: ART_STYLES.length,
    themes: themes.length,
    cards: ART_STYLES.length * themes.length,
    bytes: Buffer.byteLength(html),
  };
}
